# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ANLAM ARAYIŞI: HİKÂYE (KURMACA) VE ANI (GERÇEKLİK) KARŞILAŞTIRMASI</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">HİKÂYE / ÖYKÜ (SANATSAL METİN)</text>\n  <text x="35" y="92" font-size="11" font-weight="bold" fill="#6b21a8">• Gerçeklik İlişkisi: Kurmaca (İtibari) Gerçeklik</text>\n  <text x="45" y="108" font-size="10" fill="#581c87">Dış dünyadaki gerçeklik yazarın hayal gücüyle</text>\n  <text x="45" y="122" font-size="10" fill="#581c87">yeniden kurgulanır; kanıtlama amacı güdülmez.</text>\n  <text x="35" y="144" font-size="11" font-weight="bold" fill="#6b21a8">• Anlatıcı: Kurmaca Anlatıcı</text>\n  <text x="45" y="160" font-size="10" fill="#581c87">Yazarın kendisi değil, metin için üretilmiş sestir.</text>\n  <text x="35" y="182" font-size="11" font-weight="bold" fill="#6b21a8">• Dört Yapı Unsuru:</text>\n  <text x="45" y="198" font-size="10" fill="#581c87">Olay Örgüsü, Kişiler (Tip ve Karakter), Mekân, Zaman.</text>\n  <text x="35" y="222" font-size="10.5" font-weight="bold" fill="#7e22ce">→ Amaç: Okurda estetik zevk ve duygu uyandırmak</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">ANI / HATIRA (ÖĞRETİCİ METİN)</text>\n  <text x="375" y="92" font-size="11" font-weight="bold" fill="#1e3a8a">• Gerçeklik İlişkisi: Yaşanmış Somut Gerçeklik</text>\n  <text x="385" y="108" font-size="10" fill="#1e40af">Yazarın bizzat yaşadığı veya tanık olduğu olaylar</text>\n  <text x="385" y="122" font-size="10" fill="#1e40af">üzerinden zaman geçtikten sonra bellekle yazılır.</text>\n  <text x="375" y="144" font-size="11" font-weight="bold" fill="#1e3a8a">• Anlatıcı: Yazarın Bizzat Kendisi (1. Tekil Kişi)</text>\n  <text x="385" y="160" font-size="10" fill="#1e40af">Gerçek kişi, yer ve zaman unsurlarına bağlı kalınır.</text>\n  <text x="375" y="182" font-size="11" font-weight="bold" fill="#1e3a8a">• Anlatım Tutumu: Öznel ve Nesnel Yargılar</text>\n  <text x="385" y="198" font-size="10" fill="#1e40af">Tarihsel belgelere yardımcı olur, kişisel izlenim taşır.</text>\n  <text x="375" y="222" font-size="10.5" font-weight="bold" fill="#1d4ed8">→ Amaç: Yaşam tecrübesini ve tanıklığı aktarmak</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ANLATMAYA BAĞLI EDEBİ METİNLERDE ÜÇ TEMEL BAKIŞ AÇISI</text>\n  <rect x="20" y="45" width="212" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="126" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">1. HÂKİM (İLAHİ / TANRISAL)</text>\n  <text x="32" y="90" font-size="10.5" font-weight="bold" fill="#78350f">• Şahıs: 3. Tekil Kişi (O / Onlar)</text>\n  <text x="32" y="110" font-size="10.5" font-weight="bold" fill="#b91c1c">• Bilgi Sınırı: SINIRSIZ</text>\n  <text x="32" y="130" font-size="10" fill="#92400e">- Kahramanların zihinlerinden geçen</text>\n  <text x="38" y="144" font-size="10" fill="#92400e">gizli düşünceleri ve niyetleri okur.</text>\n  <text x="32" y="164" font-size="10" fill="#92400e">- Olayların geçmişini ve gelecekte</text>\n  <text x="38" y="178" font-size="10" fill="#92400e">ne olacağını önceden bilir.</text>\n  <text x="32" y="202" font-size="9.5" font-style="italic" fill="#78350f">Örn: "İçini derin bir pişmanlık</text>\n  <text x="32" y="216" font-size="9.5" font-style="italic" fill="#78350f">kapladı, çocukluğunu anımsadı."</text>\n  <rect x="244" y="45" width="212" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. KAHRAMAN (BEN)</text>\n  <text x="256" y="90" font-size="10.5" font-weight="bold" fill="#14532d">• Şahıs: 1. Tekil Kişi (Ben / Biz)</text>\n  <text x="256" y="110" font-size="10.5" font-weight="bold" fill="#15803d">• Bilgi Sınırı: KENDİ DENEYİMİ</text>\n  <text x="256" y="130" font-size="10" fill="#166534">- Anlatıcı, olay örgüsünün içindeki</text>\n  <text x="262" y="144" font-size="10" fill="#166534">kahramanlardan biridir.</text>\n  <text x="256" y="164" font-size="10" fill="#166534">- Kendi gördüğü, duyduğu, yaşadığı</text>\n  <text x="262" y="178" font-size="10" fill="#166534">ve hissettiği kadarıyla anlatır.</text>\n  <text x="256" y="202" font-size="9.5" font-style="italic" fill="#14532d">Örn: "Kapıyı yavaşça açtım,</text>\n  <text x="256" y="216" font-size="9.5" font-style="italic" fill="#14532d">içeride kimseyi göremedim."</text>\n  <rect x="468" y="45" width="212" height="195" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="574" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#0369a1">3. GÖZLEMCİ (MÜŞAHİT)</text>\n  <text x="480" y="90" font-size="10.5" font-weight="bold" fill="#0c4a6e">• Şahıs: 3. Tekil Kişi (O / Onlar)</text>\n  <text x="480" y="110" font-size="10.5" font-weight="bold" fill="#0369a1">• Bilgi Sınırı: KAMERA GÖZLEMİ</text>\n  <text x="480" y="130" font-size="10" fill="#075985">- Olayları dışarıdan tarafsız bir</text>\n  <text x="486" y="144" font-size="10" fill="#075985">ayna veya kamera gibi yansıtır.</text>\n  <text x="480" y="164" font-size="10" fill="#075985">- Kahramanların zihnine giremez,</text>\n  <text x="486" y="178" font-size="10" fill="#075985">dış davranışlarını aktarır.</text>\n  <text x="480" y="202" font-size="9.5" font-style="italic" fill="#0c4a6e">Örn: "Paltosunu giydi, sessizce</text>\n  <text x="480" y="216" font-size="9.5" font-style="italic" fill="#0c4a6e">sokağın köşesinden yürüdü."</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ANLATIM BİÇİMLERİ VE MODERN HİKÂYE ANLATIM TEKNİKLERİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#0e7490">1. ANLATIM BİÇİMLERİ VE DIŞ TEKNİKLER</text>\n  <text x="35" y="92" font-size="10.5" font-weight="bold" fill="#155e75">• Öyküleyici Anlatım (Video / Hareket):</text>\n  <text x="45" y="108" font-size="10" fill="#0e7490">Olayların kişi, yer ve zaman akışı içinde verilmesi.</text>\n  <text x="35" y="130" font-size="10.5" font-weight="bold" fill="#155e75">• Betimleyici Anlatım (Fotoğraf / Tasvir):</text>\n  <text x="45" y="146" font-size="10" fill="#0e7490">Mekân ve kişilerin beş duyuyla sözcüklerle resmedilmesi.</text>\n  <text x="35" y="168" font-size="10.5" font-weight="bold" fill="#155e75">• Gösterme (Sahneleme) ve Diyalog:</text>\n  <text x="45" y="184" font-size="10" fill="#0e7490">Kişilerin karşılıklı konuşmasıyla olayın canlandırılması.</text>\n  <text x="35" y="206" font-size="10.5" font-weight="bold" fill="#155e75">• Özetleme ve Geriye Dönüş (Flashback):</text>\n  <text x="45" y="222" font-size="10" fill="#0e7490">Uzun süreyi kısaltma ve geçmişteki anıya dönme.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">2. İÇ DÜNYAYI YANSITAN TEKNİKLER</text>\n  <text x="375" y="92" font-size="10.5" font-weight="bold" fill="#881337">• İç Çözümleme (Hâkim Anlatıcı Açıklar):</text>\n  <text x="385" y="108" font-size="10" fill="#9f1239">Kahramanın duyguları ve psikolojisi 3. tekil şahısla</text>\n  <text x="385" y="122" font-size="10" fill="#9f1239">anlatıcı tarafından mantıklı biçimde çözümlenir.</text>\n  <text x="375" y="146" font-size="10.5" font-weight="bold" fill="#881337">• İç Konuşma / İç Monolog (Kurallı Cümleler):</text>\n  <text x="385" y="162" font-size="10" fill="#9f1239">Anlatıcı aradan çekilir; kahraman kendi kendisiyle</text>\n  <text x="385" y="176" font-size="10" fill="#9f1239">1. tekil şahısla ve düzgün cümlelerle sessizce konuşur.</text>\n  <text x="375" y="200" font-size="10.5" font-weight="bold" fill="#881337">• Bilinç Akışı (Serbest Çağrışım / Kesik İmgeler):</text>\n  <text x="385" y="216" font-size="10" fill="#9f1239">Zihindeki düşünceler mantık sırası ve dil bilgisi bağı</text>\n  <text x="385" y="230" font-size="10" fill="#9f1239">olmadan daldan dala atlayarak peş peşe sıralanır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
